import React from "react";
import { LineChart, Line, XAxis, YAxis, Tooltip, CartesianGrid, ResponsiveContainer } from "recharts";

export default function TrafficChart({ alerts = [] }) {
  // Build simple time‑bucketed data (last 5 minutes)
  const safeAlerts = Array.isArray(alerts) ? alerts : [];
  const now = Date.now();
  const data = Array.from({ length: 5 }, (_, i) => {
    const minute = new Date(now - i * 60000);
    const count = safeAlerts.filter(
      a => a && a.detected_at && new Date(a.detected_at) > minute
    ).length;
    return {
      time: minute.toLocaleTimeString([], { minute: "2-digit" }),
      count,
    };
  }).reverse();

  return (
    <div style={{ width: "100%", height: 260 }}>
      <ResponsiveContainer width="100%" height="100%">
        <LineChart data={data} margin={{ top: 10, right: 20, left: -20, bottom: 0 }}>
          <CartesianGrid strokeDasharray="3 3" stroke="#f1f3f5" />
          <XAxis dataKey="time" stroke="#868e96" fontSize="0.8rem" />
          <YAxis allowDecimals={false} stroke="#868e96" fontSize="0.8rem" />
          <Tooltip contentStyle={{ borderRadius: "8px", border: "1px solid #ced4da" }} />
          <Line type="monotone" dataKey="count" stroke="#1890ff" strokeWidth={2.5} dot={{ r: 4, fill: "#1890ff" }} />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
}
